import React, { useEffect, useState, useRef } from "react";



import { getStore,  gen16CodeId,  ObjectKeys, fetchEncryptStream, convertArray2Obj, convertArray2ObjGroupby, hasWritePrivilege } from "../../../stores/Utils";

import {SearchInput_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"

import {  getall_feedfMbl, search_feedfMbl, resume_feedfMbl, getall_categories, search_categories } from "../services/server_fetching";
import { getall_subaccount, get_balances_by_type } from "../../CuentasContables/services/server_fetching";

import { useNavigate } from "react-router";
import CategoriesMobileItem from "./ItemCategoriesMobile";
import AddCategoriesMobile from "./AddCategoriesMobile";



const SearchInput = SearchInput_Cmpt();




const CategoriesMobileDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const [loading, set_loading] = useState(false);


	const navigate = useNavigate();


	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			get_balances_by_type("global_accounts","global_account_params",getallAccount);
			getallCategoriesMobile();
		}
	});


	
	const getallAccount =  () => {
		getall_subaccount(getallCategoriesMobile);
	}

	const getallCategoriesMobile =  () => {
		getall_categories(cb_result);
	}

	


	



	

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}


	const handle_search =  (v) => {
		set_loading(true)
		search_categories(cb_result)
	}


	const handle_getall =  (v) => {
		getall_categories(cb_result)
	}

	const cb_result = async (f, v) => {
		set_obs(gen16CodeId())
		set_loading(false);
	};


	const goToFutureChecks =  (v) => {
		
	}


	const addCategories =  (v) => {
		
	
			let modal_data = {};
			modal_data["zIndex"] = 450;
			modal_data["height"] = "80vh";
			// data['observeResize']=true;
			modal_data["props"] = { minHeight: "1vh", overlay: true };
			modal_data["content"] = 
				<AddCategoriesMobile />
			
			OpenModal(modal_data);
	}

	
	return (

	<div className="">
		<div className="accounts_header">
			<h2>Categorias</h2>
			{hasWritePrivilege()?
			<div className="_dsplFlx ">
				
				<p className="group_title addBtn purple" onClick={addCategories}>
					Agregar 
				</p>
				
				
					
			
			</div>
			:null}
			<div className="_dsplFlx " style={{marginTop:14}}>
				<SearchInput
					placeholder={"Buscar ...."} 
					width={360}
					obs={set_obs}
					fetchData={handle_search}
					loading={loading}
					change={handleChange}
					callempty={handle_getall}
					keyFlds={"search_categories"}
				/>
				<div className="flexSpace"/>
				<div className="_dsplFlx ">
					<div className="total_comprobante_title">
						No de categorias: 
					</div>
					<div className="total_comprobante gray">
						<span>
							{ObjectKeys(getStore("categories_list"))?.length}
						</span>
					</div>
					
				</div>
			</div>
		</div>
		
			<div className="providers_container scollVh">
				{getStore("categories_list") && ObjectKeys(getStore("categories_list"))?.map(cid=>{
					return (
						<CategoriesMobileItem
							data={getStore("categories_list")[cid]} 
							elmId={cid} 
							key={cid}
							handleRefreshAll={handle_getall}
						/>
					)
				})}
			</div>
		
		</div>
	);
};

export default CategoriesMobileDashboard;
