import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, parseDate, fetchPostH, getUrlServerSide, ObjectKeys, hasWritePrivilege, parseDateMMDDYYYY } from "../../../stores/Utils";

import "./dashboard.css"
import { OpenModal } from "../../../components/DialogHRM";
import { getall_feedfMbl,  delete_feedfMbl } from "../services/server_fetching";
import { SvgIcon_Cmpt, LoadingColorSpinner_Cmpt } from "../../../components";
import DeleteAlert from "./deleteAlert";
import { useNavigate } from "react-router";
import { getall_collects, getall_toPay } from "../../Cobros/services/server_fetching";
import UpdCategoriesMobile from "./UpdCategoriesMobile";

const Svg = SvgIcon_Cmpt();



const CategoriesMobileItem  = ({ data, elmId, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const [loadingAmount, set_loadingAmount] = useState(0);

	const navigate = useNavigate();

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())
		}
	});

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	
	const refreshAccs =  () => {
		getall_feedfMbl(updObs)
	}

	const update = async () => {
		if(hasWritePrivilege()){
			updStore("upd_categoriesM", data);
			updStore("upd_categoriesM_bck", {...data});
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			modaldata["content"] = <UpdCategoriesMobile confirm={refreshAccs} />;
			OpenModal(modaldata);
		}
	}


	


	const deleteComprobante =  () => {
		delete_feedfMbl(data?.movementId, handleRefreshAll);
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCallModal", Date.now()+320);
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <DeleteAlert confirm={deleteComprobante} item={data} />
			OpenModal(modaldata);
		}
	}

	
	return (
		<div className="item_acc">
			<div className="_dsplFlx operation_item_box" >
				<div className="icon_revision" >
					<Svg 
						name={data.account ? "success":"alert"} 
						color={data.account? "var(--hrm_palette-success-fg)":"var(--hrm_palette-selected-nav-text)"}
					/>
				</div>
				<div className="_dsplFlx tr_bar_90" onClick={update}>
					<div className=" tr_bar_25" >
						{data?.name} 
					</div>
					<div className=" tr_bar_45  font_onm" style={{marginLeft: 9}}>
					
						
					</div>
					<div className=" tr_bar_15" style={{ color:data.movementType==="expense"?"var(--hrm_palette-selected-nav-text)": "var( --hrm_palette-blue-purple)"}}>
						{data?.type }
					</div>
				</div>
				<div className="flexSpace"/>
				<div className="icon tr_bar_5" onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				
			</div>
			
		</div>
	)
}
export default CategoriesMobileItem;